                if (r != null)
                {
                    r.GetPropertyBlock(_propBlock);
                    _propBlock.SetColor(ColorPropertyId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));
                    r.SetPropertyBlock(_propBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "A função FindObjectsOfType vasculha toda a árvore de objetos do jogo. Fazer isso 60 vezes por segundo (ou várias vezes dentro de um loop) equivale a procurar um livro lendo a estante inteira repetidamente em vez de guardar onde o livro está guardado. A melhor prática é guardar a referência do objeto (fazer cache) uma única vez no Start() ou Awake(), ou usar eventos e listas gerenciadas."
    }
  ],
  "dicas_level_design": null
